unsafe fn add_func(mut lil: lil_t, mut name: *const c_char) -> lil_func_t {
    let cmd = find_cmd(lil, name);
    if !cmd.is_null() {
        if !(*cmd).argnames.is_null() {
            lil_free_list((*cmd).argnames);
        }
        lil_free_value((*cmd).code);
        (*cmd).argnames = ::core::ptr::null_mut::<_lil_list_t>();
        (*cmd).code = ::core::ptr::null_mut::<_lil_value_t>();
        (*cmd).proc_0 = None;
        return cmd;
    }

    let cmd = calloc(1 as size_t, ::core::mem::size_of::<_lil_func_t>() as size_t) as lil_func_t;
    if cmd.is_null() {
        return ::core::ptr::null_mut::<_lil_func_t>();
    }

    (*cmd).name = strclone(name);

    let lilp = &mut *lil;
    let old_cmds = lilp.cmds;
    let new_cmd = realloc(
        lilp.cmd as *mut c_void,
        (::core::mem::size_of::<lil_func_t>() as size_t).wrapping_mul(old_cmds.wrapping_add(1)),
    ) as *mut lil_func_t;

    if new_cmd.is_null() {
        free(cmd as *mut c_void);
        return ::core::ptr::null_mut::<_lil_func_t>();
    }

    lilp.cmd = new_cmd;
    lilp.cmds = old_cmds.wrapping_add(1);
    // SAFETY: `new_cmd` points to an allocation large enough for `old_cmds + 1` elements after successful realloc.
    *new_cmd.add(old_cmds) = cmd;

    hm_put(&raw mut lilp.cmdmap, name, cmd as *mut c_void);
    cmd
}

